#include "ksArpEventTask.h"
#include <iostream>
#include <vector>
#include <tuple>
#include <stdexcept>
using T=ks::ArpEventTask;using S=T::Stage;using K=T::Kind;using C=T::Child;using Event=std::tuple<S,uint32_t>;
void check(bool v,const char* why){if(!v)throw std::runtime_error(why);}
int main(){try{uint64_t cases=0;auto verify=[&](K kind,unsigned a,unsigned b,unsigned mode,unsigned policy,unsigned held,unsigned shape,unsigned mask,unsigned reply,unsigned latency){
 T t(kind,17,uint8_t(a),192);std::vector<Event> writes;std::vector<C> children;unsigned reads=0,loops=0;const unsigned inputPart=kind==K::Gate||kind==K::Chord?199:17;unsigned observedNotes=0;uint8_t emittedVelocity=192;
 while(!t.complete()){
  check(++loops<20000,"Event task stalled");if(t.awaitingChild()){const auto child=t.child();children.push_back(child);switch(child){case C::Part:check(t.resumePart(199),"Part reply rejected");break;case C::Held:check(t.resumeHeld(199,held!=0),"Held reply rejected");break;case C::ReleaseGate:case C::Append:case C::ReleaseHeld:check(t.resumePart(199),"Nested part reply rejected");break;case C::MidiOn:case C::MidiOff:check(t.resumeMidi(uint8_t(reply)),"MIDI policy reply rejected");break;case C::Emit:check(t.key()==uint16_t(0x8000u+uint16_t(t.listOffset())),"Chord key delivery differs");++observedNotes;check(t.resumeChild(),"Emit reply rejected");break;case C::Off:check(t.note()==uint8_t(36+observedNotes),"Queue note delivery differs");++observedNotes;check(t.resumeChild(),"Off reply rejected");break;case C::Play:emittedVelocity=t.velocity();check(t.playedNote()==uint8_t(a+uint8_t(shape*12)),"Transposed delivery differs");check(t.resumeChild(),"Play reply rejected");break;default:check(t.resumeChild(),"Child reply rejected");break;}continue;}
  auto read=[&](S s)->uint32_t{++reads;switch(s){case S::AppendReadMode:case S::ChordReadMode:case S::ChordReadCurrentMode:case S::ChordReadFinalMode:case S::ResetReadMode:return mode;case S::AppendReadCount:case S::AppendReadIndex:case S::GateReadCount:return a;case S::AppendReadState:case S::GateReadState:return b;case S::AppendReadPhase:case S::GateReadPhase:return uint16_t(a*257);case S::AppendReadDuration:case S::GateReadExpiry:return uint16_t(b*257);case S::GateReadVoices:return shape;case S::GateReadShape:return reply;case S::GateReadNote:return uint8_t(36+t.cursor());case S::OffReadMask:case S::EmitReadMask:return mask;case S::OffReadPolicy:case S::ChordReadPolicy:case S::EmitReadPolicy:case S::ResetReadFirstPolicy:case S::ResetReadPolicy:return policy;case S::ChordReadQueue:return b;case S::ChordReadHeld:return a;case S::ChordReadOctave:case S::EmitReadOctave:case S::ResetReadOctaves:return shape;case S::ChordReadOldOctave:return uint8_t(shape+17);case S::ChordReadKey:return uint16_t(0x8000u+uint16_t(t.listOffset()));case S::EmitReadOverride:return mode;case S::EmitReadVelocity:return 127;default:throw std::runtime_error("Unexpected pure event read");}};
  auto write=[&](S s,uint32_t data){writes.emplace_back(s,data);};auto timing=[&](S){return latency;};const auto cost=t.nextClocks(t.publication()?latency:3);check(cost>0,"Event deadline stalled");const auto before=reads+writes.size();check(!t.advanceBefore(cost-1,read,write,timing)&&reads+writes.size()==before,"Early event access");check(t.advanceBefore(cost,read,write,timing)==cost,"Event deadline differs");
 }
 std::vector<Event> ew;std::vector<C> ec;switch(kind){
 case K::Append:{const bool release=!(mode&128)&&a==0&&b&&b!=2;if(!(mode&128))ew.emplace_back(S::AppendPublishExpiry,uint16_t(a*257+b*257));if(release)ec.push_back(C::ReleaseGate);ew.emplace_back(S::AppendPublishNote,uint8_t(a));ew.emplace_back(S::AppendPublishCount,uint8_t(a+1));ew.emplace_back(S::AppendPublishMirror,uint8_t(a+1));ew.emplace_back(S::AppendPublishState,1);break;}
 case K::Gate:case K::DirectGate:{if(kind==K::Gate)ec.push_back(C::Part);const unsigned phase=uint16_t(a*257),expiry=uint16_t(b*257),difference=uint16_t(phase-expiry);const bool admitted=kind==K::DirectGate||b&& (b==2||(!(difference&32768)&&phase>=expiry));if(admitted){if(kind==K::Gate&&b!=2)ew.emplace_back(S::GatePublishReleased,2);ec.push_back(C::Held);const bool hold=held&&shape<=1&&reply==127;if(!hold){const unsigned count=a?a:256;for(unsigned i=0;i<count;++i)ec.push_back(C::Off);ew.emplace_back(S::GatePublishIdle,0);ew.emplace_back(S::GatePublishEmpty,0);check(observedNotes==count,"Queue zero/byte count differs");}}break;}
 case K::Off:{if(mask&1){const unsigned route=policy&96;if(route)ec.push_back(C::MidiOff);const unsigned returned=route?reply:0;if(returned==0||returned==64)ec.push_back(C::VoiceOff);}break;}
 case K::Chord:{ec.push_back(C::Part);if(policy&4&&mode&32&&b&&a>b){ew.emplace_back(S::ChordPublishCount,b);ew.emplace_back(S::ChordPublishPending,mode|128);ew.emplace_back(S::ChordPublishOctave,shape);for(unsigned i=0;i<a-b;++i)ec.push_back(C::Emit);check(observedNotes==a-b,"Chord new-note count differs");ew.emplace_back(S::ChordRestoreOctave,uint8_t(shape+17));ew.emplace_back(S::ChordPublishFinalMode,mode&127);check(t.listOffset()==240+uint8_t(a*2)-2*int(a-b),"Chord wrapped list traversal differs");}break;}
 case K::Emit:{ew.emplace_back(S::EmitPublishLast,uint8_t(a));const unsigned pitch=uint8_t(a+uint8_t(shape*12));if(!(pitch&128)){ec.push_back(C::Append);if(mask&1){const unsigned route=policy&96;if(route)ec.push_back(C::MidiOn);const unsigned returned=route?reply:0;if(returned==0||returned==64){ec.push_back(C::Play);check(emittedVelocity==(mode?127:192),"Velocity override differs");}ew.emplace_back(S::EmitPublishWork,1);}}break;}
 case K::Reset:{ec.push_back(C::Held);if(!held||policy&8)ec.push_back(C::Phase);if(!(policy&8)&&policy&16)ec.push_back(C::Held);if(!(!(policy&8)&&policy&16&&held)){ew.emplace_back(S::ResetPublishLast,mode&1?0:127);ew.emplace_back(S::ResetPublishDirection,mode&1?0:1);ew.emplace_back(S::ResetPublishOctave,mode&1?0:shape);ew.emplace_back(S::ResetPublishIndex,0);}ec.push_back(C::ReleaseHeld);ew.emplace_back(S::ResetPublishSentinel,255);ec.push_back(C::Refresh);break;}
 }
 check(writes==ew,"Event publications differ");check(children==ec,"Event child ordering/admission differs");check(t.part()==(children.empty()?inputPart:kind==K::Off?17:kind==K::Emit?((uint8_t(a+uint8_t(shape*12))&128)?17:199):kind==K::Append&&children.empty()?17:199),"Event part reply mismatch");++cases;
 };
 for(unsigned latency:{0u,3u}){
  for(unsigned a=0;a<256;++a)for(unsigned b:{0u,1u,2u,255u})for(unsigned mode=0;mode<256;++mode)verify(K::Append,a,b,mode,0,0,0,0,0,latency);
  for(unsigned a=0;a<256;++a)for(unsigned b:{0u,1u,2u,127u,128u,255u})for(unsigned shape:{0u,1u,2u,255u})for(unsigned held:{0u,1u})for(unsigned gate:{64u,127u})for(auto k:{K::Gate,K::DirectGate})verify(k,a,b,0,0,held,shape,0,gate,latency);
  for(unsigned policy=0;policy<256;++policy)for(unsigned mask=0;mask<256;++mask)for(unsigned reply:{0u,32u,64u,96u,255u})verify(K::Off,60,0,0,policy,0,0,mask,reply,latency);
  for(unsigned a=0;a<256;++a)for(unsigned b=0;b<256;++b)verify(K::Chord,a,b,32,4,0,3,0,0,latency);
  for(unsigned a=0;a<256;++a)for(unsigned octave=0;octave<256;++octave)for(unsigned route:{0u,32u,64u,96u})verify(K::Emit,a,0,a&1,route,0,octave,1,route==96?255:route,latency);
  for(unsigned mode=0;mode<256;++mode)for(unsigned policy=0;policy<256;++policy)for(unsigned held:{0u,1u})verify(K::Reset,0,0,mode,policy,held,uint8_t(mode+policy),0,0,latency);
 }
 std::cout<<"PASS: "<<cases<<" pure arp event tasks, independent queue/hold/expiry/route/chord/transpose/reset oracles, full-byte arithmetic, typed live replies and exact early deadlines\n";
}catch(const std::exception& e){std::cerr<<e.what()<<'\n';return 1;}}
